<script setup lang="ts">
import {ref,watch} from 'vue';import {Link,usePage} from '@inertiajs/vue3';
import Modal from './Modal.vue';import BalanceChart from './BalanceChart.vue';import Pagination from './Pagination.vue';
import LoadingState from './LoadingState.vue';
import {json,money,dateLabel} from '../lib/format';
const props=defineProps<{id:string;catalog:any;embedded?:boolean;initialDetail?:any}>();const emit=defineEmits<{close:[];edit:[kind:string,record:any];connection:[id:string];transaction:[id:string]}>();
const detail=ref<any>(props.initialDetail),error=ref(''),search=ref(''),hidden=ref(false),timeline=ref(true),loading=ref(false);const page=usePage<any>();let requestNumber=0;
async function load(url?:string){const request=++requestNumber;loading.value=true;error.value='';try{const result=await json(url||'/accounts/'+props.id+'?'+new URLSearchParams({search:search.value,show_hidden:hidden.value?'1':'0'}));if(request===requestNumber)detail.value=result;}catch(e:any){if(request===requestNumber)error.value=e.message;}finally{if(request===requestNumber)loading.value=false;}}
watch(()=>props.id,()=>{detail.value=props.initialDetail;if(!detail.value)load();},{immediate:true});
watch(()=>props.initialDetail,(value)=>{if(value){requestNumber++;loading.value=false;detail.value=value;}});
const categoryName=(id:string)=>{const category=props.catalog.categories.find((c:any)=>c.id===id);const parent=props.catalog.categories.find((c:any)=>c.id===category?.parent_id);return category?(parent?parent.name+' › ':'')+category.name:'Uncategorized';};
</script>
<template><component :is="embedded?'section':Modal" :open="true" :title="detail?.account.name||'Account details'" @close="emit('close')"><div :class="embedded?'space-y-5':'space-y-5 p-6'" :aria-busy="loading">
 <p v-if="error" role="alert" class="callout text-warning!">{{error}} <button class="underline" @click="load()">Try again</button></p><LoadingState v-if="!detail" :loading="loading" label="Loading account"/>
 <div v-else class="space-y-5" :class="loading?'opacity-50 pointer-events-none':''"><div class="grid items-start gap-5" :class="detail.connection?'xl:grid-cols-[minmax(0,1fr)_260px]':''"><BalanceChart :accounts="[detail.account]" :history="detail.balances" :limits="detail.limits" :today="page.props.today" single-account :initial-view="detail.account.type==='credit_card'?'credit_card':detail.account.type==='loan'?'loan':detail.account.type==='investment'?'investment':'cash'"/>
 <aside v-if="detail.connection" class="panel p-4"><div class="flex items-center justify-between"><h2 class="text-sm!">Connection</h2><span class="badge" :class="detail.connection.state!=='active'?'badge-warning':''">{{detail.connection.state.replaceAll('_',' ')}}</span></div><p v-if="detail.account.latest_error||detail.connection.latest_error" class="mt-4 rounded-md bg-warning-soft p-3 text-xs text-warning">The latest sync failed. Imported history is retained. Review the connection to reconnect or try again.</p><dl class="mt-4 grid grid-cols-[70px_1fr] gap-3 text-xs"><dt class="text-muted">Provider</dt><dd>{{detail.connection.name}}</dd><dt class="text-muted">Last sync</dt><dd>{{dateLabel(detail.account.last_success_at||detail.connection.last_full_success_at)}}</dd><dt class="text-muted">Import from</dt><dd>{{dateLabel(detail.account.import_start_date)}}</dd></dl><button class="mt-5 text-xs text-income underline" @click="emit('connection',detail.connection.id)">Manage connection & import dates</button></aside></div>
 <section v-if="detail.account.type==='credit_card'" class="panel overflow-x-auto"><div class="flex items-center justify-between border-b border-line px-4 py-4"><div><h2>Credit limit history</h2><p class="help mt-1">Changes affect usage from their recorded date.</p></div><button class="btn min-h-8! text-xs!" @click="emit('edit','limit',{...detail.account,limit_cents:detail.limits.find((limit:any)=>limit.effective_date<=page.props.today)?.limit_cents})">Change limit</button></div><table><thead><tr><th>Effective date</th><th>Limit</th><th>Change</th><th>Note</th><th/></tr></thead><tbody><tr v-for="(limit,index) in detail.limits" :key="limit.id"><td>{{dateLabel(limit.effective_date)}}</td><td class="money">{{money(limit.limit_cents)}}</td><td class="money">{{detail.limits[Number(index)+1]?money(Number(limit.limit_cents)-Number(detail.limits[Number(index)+1].limit_cents)):'Initial limit'}}</td><td class="text-muted">{{limit.note||'—'}}</td><td><button class="text-xs text-income underline" @click="emit('edit','limit',{...detail.account,loan_id:detail.loan_id,limit_cents:limit.limit_cents,effective_date:limit.effective_date,note:limit.note})">Correct</button></td></tr></tbody></table><p v-if="!detail.limits.length" class="help px-4 py-6">No limit recorded. Add a credit limit to see card usage.</p></section>
 <section class="panel overflow-x-auto"><div class="flex flex-wrap items-center justify-between gap-3 px-4 py-4"><h2>{{detail.account.source==='manual'?'Transactions and balance updates':'Transactions'}}</h2><Link :href="'/transactions?account='+id" class="help text-income! underline">Open in Transactions</Link></div><form class="flex flex-wrap items-center gap-3 px-4 pb-4" @submit.prevent="load()"><input v-model="search" aria-label="Search account activity" placeholder="Search payees" class="max-w-xs"/><button class="btn min-h-9! text-xs!">Search</button><label class="flex items-center gap-2 text-xs font-normal"><input v-model="hidden" type="checkbox" @change="load()"/>Show hidden</label><label v-if="detail.account.source==='manual'" class="flex items-center gap-2 text-xs font-normal"><input v-model="timeline" type="checkbox"/>Include balance updates</label></form>
 <table><thead><tr><th>Date</th><th>Description</th><th>{{detail.account.source==='manual'?'Balance effect':'Category'}}</th><th class="text-right!">Amount</th><th/></tr></thead><tbody><tr v-for="row in (timeline&&detail.account.source==='manual'?detail.timeline.data:detail.transactions.data)" :key="row.id" :class="row.hidden?'opacity-50':''"><td class="text-xs text-muted">{{dateLabel(row.date||row.transaction_date)}}</td><td><button v-if="row.payee" class="font-medium hover:underline" @click="emit('transaction',row.id)">{{row.payee}}</button><span v-else class="font-medium">Balance set to {{money(row.balance_cents)}}</span><span v-if="row.status==='pending'" class="badge badge-pending ml-2">Pending</span><p class="help mt-1">{{row.payee?categoryName(row.category_id):row.kind.replaceAll('_',' ')}}<span v-if="row.hidden"> · Hidden</span></p></td><td class="text-xs text-muted">{{detail.account.source==='manual'?(row.delta_cents!==null&&row.delta_cents!==undefined?money(row.delta_cents):'Balance update'):categoryName(row.category_id)}}</td><td class="money text-right" :class="row.payee&&Number(row.amount_cents)>0?'text-income':''">{{money(row.payee?row.amount_cents:row.balance_cents)}}</td><td><button v-if="row.payee" class="text-xs text-income underline" @click="emit('transaction',row.id)">View</button></td></tr></tbody></table>
 <div v-if="!(timeline&&detail.account.source==='manual'?detail.timeline.data:detail.transactions.data).length" class="empty"><p>{{search||hidden?'No activity matches this view.':'No activity recorded yet.'}}</p><button v-if="search||hidden" class="btn" @click="search='';hidden=false;load()">Clear filters</button><button v-else-if="detail.account.source==='manual'&&detail.account.type!=='loan'" class="btn" @click="emit('edit','transaction',{account_id:id})">Add transaction</button></div><Pagination :records="timeline&&detail.account.source==='manual'?detail.timeline:detail.transactions" asynchronous @load="load"/></section>
 <p v-if="detail.account.notes" class="help whitespace-pre-wrap">{{detail.account.notes}}</p><p v-if="detail.account.source==='manual'" class="help">Adding a transaction can update the balance once. Editing or deleting a transaction keeps its recorded balance effect. Use Update balance to change the recorded balance.</p>
 </div></div></component></template>